import numpy as np

def generate_hex_grids():
    candidates = []
    # Test different number of rows (e.g. 5, 6, 7) and columns (e.g. 5, 6, 7)
    for nrows in range(5, 8):
        for ncols in range(5, 8):
            for stagger_odd in [True, False]:
                # spacing
                dx = 1.0 / ncols
                dy = 1.0 / nrows
                pts = []
                for r in range(nrows):
                    shift = 0.5 * dx if (r % 2 == 1 if stagger_odd else r % 2 == 0) else 0.0
                    y = (r + 0.5) * dy
                    for c in range(ncols):
                        x = (c + 0.5) * dx + shift - 0.25 * dx
                        if 0.05 < x < 0.95 and 0.05 < y < 0.95:
                            d = np.hypot(x - 0.37, y - 0.58)
                            if d > 0.18:
                                pts.append((x, y))
                if len(pts) >= 32:
                    candidates.append(np.array(pts))
    print(f'Generated {len(candidates)} candidate grids with >= 32 points')

generate_hex_grids()
